mapper.update:
UPDATE pf.capability_materialization_command SET state='COMMITTED',receipt_json=CAST(#{json} AS jsonb),receipt_hash=#{hash},revision=revision+1,
 updated_at=clock_timestamp()
WHERE operation_id=#{command.operationId} AND command_id=#{command.commandId} AND request_hash IS NOT NULL AND state='RUNNING'
 AND space_id=#{command.spaceId} AND task_id=#{command.taskId} AND attempt_id=#{command.attemptId} AND actor_id=#{command.actorId}
 AND owner_id=#{command.ownerId} AND workspace_id=#{command.workspaceId} AND fence=#{command.fence} AND manifest_hash=#{command.manifestHash}

UPDATE pf.capability_materialization_command SET state='BLOCKED',error_code=#{code},
 receipt_json=COALESCE(CAST(#{json} AS jsonb),receipt_json),
 receipt_hash=COALESCE(#{hash},receipt_hash),revision=revision+1,updated_at=clock_timestamp()
WHERE operation_id=#{command.operationId} AND command_id=#{command.commandId} AND state='RUNNING'
 AND space_id=#{command.spaceId} AND task_id=#{command.taskId} AND attempt_id=#{command.attemptId}
 AND owner_id=#{command.ownerId} AND workspace_id=#{command.workspaceId} AND fence=#{command.fence} AND manifest_hash=#{command.manifestHash}

UPDATE pf.capability_materialization_command SET state='FAILED',error_code=#{code},
 receipt_json=CAST(#{json} AS jsonb),receipt_hash=#{hash},revision=revision+1,updated_at=clock_timestamp()
WHERE operation_id=#{command.operationId} AND command_id=#{command.commandId} AND state='RUNNING'
 AND space_id=#{command.spaceId} AND task_id=#{command.taskId} AND attempt_id=#{command.attemptId}
 AND owner_id=#{command.ownerId} AND workspace_id=#{command.workspaceId} AND fence=#{command.fence} AND manifest_hash=#{command.manifestHash}
